#!/usr/bin/env python

import math
import numpy as np
from multiprocessing import Pool, cpu_count

'''
All of these algorithms have been taken from the paper:
Trotmam et al, Improvements to BM25 and Language Models Examined

Here we implement all the BM25 variations mentioned.
'''


def _safe_divide(numerator, denominator):
    numerator = np.asarray(numerator, dtype=float)
    denominator = np.asarray(denominator, dtype=float)
    shape = np.broadcast(numerator, denominator).shape
    out = np.zeros(shape, dtype=float)
    return np.divide(numerator, denominator, out=out, where=denominator != 0)


class BM25:
    def __init__(self, corpus, tokenizer=None):
        self.corpus_size = 0
        self.avgdl = 0
        self.doc_freqs = []
        self.idf = {}
        self.doc_len = []
        self.tokenizer = tokenizer

        if tokenizer:
            corpus = self._tokenize_corpus(corpus)

        nd = self._initialize(corpus)
        self._calc_idf(nd)

    def _initialize(self, corpus):
        nd = {}
        num_doc = 0
        for document in corpus:
            self.doc_len.append(len(document))
            num_doc += len(document)

            frequencies = {}
            for word in document:
                if word not in frequencies:
                    frequencies[word] = 0
                frequencies[word] += 1
            self.doc_freqs.append(frequencies)

            for word, freq in frequencies.items():
                try:
                    nd[word] += 1
                except KeyError:
                    nd[word] = 1

            self.corpus_size += 1

        self.avgdl = num_doc / self.corpus_size if self.corpus_size else 0.0
        return nd

    def _tokenize_corpus(self, corpus):
        pool = Pool(cpu_count())
        tokenized_corpus = pool.map(self.tokenizer, corpus)
        return tokenized_corpus

    def _length_norm(self, doc_len):
        doc_len = np.asarray(doc_len, dtype=float)
        if self.avgdl > 0:
            return 1 - self.b + self.b * doc_len / self.avgdl
        return np.ones_like(doc_len, dtype=float)

    def _calc_idf(self, nd):
        raise NotImplementedError()

    def get_scores(self, query):
        raise NotImplementedError()

    def get_batch_scores(self, query, doc_ids):
        raise NotImplementedError()

    def get_top_n(self, query, documents, n=5):

        assert self.corpus_size == len(documents), 'The documents given do not match the index corpus!'

        if n <= 0:
            return []

        scores = self.get_scores(query)
        top_n = np.argsort(scores)[::-1][:n]
        return [documents[i] for i in top_n]


class BM25Okapi(BM25):
    def __init__(self, corpus, tokenizer=None, k1=1.5, b=0.75, epsilon=0.25):
        self.k1 = k1
        self.b = b
        self.epsilon = epsilon
        super().__init__(corpus, tokenizer)

    def _calc_idf(self, nd):
        '''
        Calculates frequencies of terms in documents and in corpus.
        This algorithm sets a floor on the idf values to eps * average_idf
        '''
        idf_sum = 0
        negative_idfs = []
        for word, freq in nd.items():
            idf = math.log(self.corpus_size - freq + 0.5) - math.log(freq + 0.5)
            self.idf[word] = idf
            idf_sum += idf
            if idf < 0:
                negative_idfs.append(word)
        self.average_idf = idf_sum / len(self.idf) if self.idf else 0.0

        eps = self.epsilon * self.average_idf
        for word in negative_idfs:
            self.idf[word] = eps

    def get_scores(self, query):
        score = np.zeros(self.corpus_size)
        doc_len = np.array(self.doc_len, dtype=float)
        norm = self._length_norm(doc_len)
        for q in query:
            q_freq = np.array([(doc.get(q) or 0) for doc in self.doc_freqs], dtype=float)
            score += (self.idf.get(q) or 0) * _safe_divide(
                q_freq * (self.k1 + 1), q_freq + self.k1 * norm
            )
        return score

    def get_batch_scores(self, query, doc_ids):
        '''
        Calculate bm25 scores between query and subset of all docs
        '''
        assert all(0 <= di < len(self.doc_freqs) for di in doc_ids)
        score = np.zeros(len(doc_ids))
        doc_len = np.array(self.doc_len, dtype=float)[doc_ids]
        norm = self._length_norm(doc_len)
        for q in query:
            q_freq = np.array([(self.doc_freqs[di].get(q) or 0) for di in doc_ids], dtype=float)
            score += (self.idf.get(q) or 0) * _safe_divide(
                q_freq * (self.k1 + 1), q_freq + self.k1 * norm
            )
        return score.tolist()


class BM25L(BM25):
    def __init__(self, corpus, tokenizer=None, k1=1.5, b=0.75, delta=0.5):
        self.k1 = k1
        self.b = b
        self.delta = delta
        super().__init__(corpus, tokenizer)

    def _calc_idf(self, nd):
        for word, freq in nd.items():
            idf = math.log(self.corpus_size + 1) - math.log(freq + 0.5)
            self.idf[word] = idf

    def get_scores(self, query):
        score = np.zeros(self.corpus_size)
        doc_len = np.array(self.doc_len, dtype=float)
        norm = self._length_norm(doc_len)
        for q in query:
            q_freq = np.array([(doc.get(q) or 0) for doc in self.doc_freqs], dtype=float)
            ctd = _safe_divide(q_freq, norm)
            score += (self.idf.get(q) or 0) * _safe_divide(
                (self.k1 + 1) * (ctd + self.delta), self.k1 + ctd + self.delta
            )
        return score

    def get_batch_scores(self, query, doc_ids):
        '''
        Calculate bm25 scores between query and subset of all docs
        '''
        assert all(0 <= di < len(self.doc_freqs) for di in doc_ids)
        score = np.zeros(len(doc_ids))
        doc_len = np.array(self.doc_len, dtype=float)[doc_ids]
        norm = self._length_norm(doc_len)
        for q in query:
            q_freq = np.array([(self.doc_freqs[di].get(q) or 0) for di in doc_ids], dtype=float)
            ctd = _safe_divide(q_freq, norm)
            score += (self.idf.get(q) or 0) * _safe_divide(
                (self.k1 + 1) * (ctd + self.delta), self.k1 + ctd + self.delta
            )
        return score.tolist()


class BM25Plus(BM25):
    def __init__(self, corpus, tokenizer=None, k1=1.5, b=0.75, delta=1):
        self.k1 = k1
        self.b = b
        self.delta = delta
        super().__init__(corpus, tokenizer)

    def _calc_idf(self, nd):
        for word, freq in nd.items():
            idf = math.log(self.corpus_size + 1) - math.log(freq)
            self.idf[word] = idf

    def get_scores(self, query):
        score = np.zeros(self.corpus_size)
        doc_len = np.array(self.doc_len, dtype=float)
        norm = self._length_norm(doc_len)
        for q in query:
            q_freq = np.array([(doc.get(q) or 0) for doc in self.doc_freqs], dtype=float)
            score += (self.idf.get(q) or 0) * (
                self.delta + _safe_divide(q_freq * (self.k1 + 1), self.k1 * norm + q_freq)
            )
        return score

    def get_batch_scores(self, query, doc_ids):
        '''
        Calculate bm25 scores between query and subset of all docs
        '''
        assert all(0 <= di < len(self.doc_freqs) for di in doc_ids)
        score = np.zeros(len(doc_ids))
        doc_len = np.array(self.doc_len, dtype=float)[doc_ids]
        norm = self._length_norm(doc_len)
        for q in query:
            q_freq = np.array([(self.doc_freqs[di].get(q) or 0) for di in doc_ids], dtype=float)
            score += (self.idf.get(q) or 0) * (
                self.delta + _safe_divide(q_freq * (self.k1 + 1), self.k1 * norm + q_freq)
            )
        return score.tolist()

